package com.healthwise.dashboard.controller;import com.healthwise.dashboard.dto.DashboardResponse;import com.healthwise.dashboard.service.DashboardService;import com.healthwise.security.CurrentUser;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/dashboard")public class DashboardController{private final DashboardService s;public DashboardController(DashboardService x){s=x;}@GetMapping public DashboardResponse get(@AuthenticationPrincipal CurrentUser u){return s.get(u.id());}}
